insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial para desbloquear o aluno nos primeiros minutos. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar e ajustar a fala ate se aproximar do neerlandes natural."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Esta licao prepara o aluno para uma situacao comum na Holanda: alguem fala neerlandes numa loja, farmacia, estacao, gemeente, consulta medica, escola ou local de trabalho, e o aluno nao entende.\r\n\r\nO objetivo nao e fingir fluencia. O objetivo e ensinar o aluno a controlar a situacao de forma educada:\r\n\r\n- dizer que nao entende\r\n- pedir ajuda\r\n- pedir repeticao\r\n- pedir fala lenta\r\n- perguntar se a pessoa fala ingles\r\n- continuar a interacao sem bloquear\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nFuncionaria da gemeente: Heeft u een afspraak?\r\nAluno: Sorry, ik begrijp het niet. Kunt u langzaam spreken?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- reconhecer frases basicas em fala lenta\r\n- reconhecer algumas formas naturais e reduzidas\r\n- dizer que nao entende\r\n- pedir ajuda de forma educada\r\n- pedir para repetir\r\n- pedir para falar devagar\r\n- perguntar se a pessoa fala ingles\r\n- fazer um mini roleplay numa situacao real\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nSorry, ik begrijp het niet. Kunt u langzaam spreken?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler, as frases:\r\n\r\n```text\r\nKunt u mij helpen?\r\nKunt u dat herhalen?\r\nSpreekt u Engels?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `sorry`\r\n\r\nTraducao PT: desculpe  \r\nTraducao EN: sorry  \r\nAudio nativo: `audio/A0-01/words/sorry.native.nl.mp3`  \r\nAproximacao inicial PT: `SO-ri`  \r\nAproximacao inicial EN: `SOR-ree`, short and light\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `sorry`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: pronunciar como \"sorri\" em portugues.\r\n- EN: prolongar demasiado como \"saaaw-ree\".\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nsorry\r\nsorry\r\nsorry, ik begrijp het niet\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres palavras e identifica `sorry`:\r\n\r\n```text\r\n1. sorry\r\n2. spreken\r\n3. helpen\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `sorry` em audio e consegue dize-lo de forma curta, educada e natural.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `ik`\r\n\r\nTraducao PT: eu  \r\nTraducao EN: I  \r\nAudio nativo: `audio/A0-01/words/ik.native.nl.mp3`  \r\nAproximacao inicial PT: `ik`  \r\nAproximacao inicial EN: `ick`, short\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `ik`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer \"ique\".\r\n- EN: alongar para \"eek\".\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nik\r\nik\r\nik begrijp\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno distingue:\r\n\r\n```text\r\nik\r\nu\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno distingue `ik` de `u` e pronuncia o `k` final.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `begrijp`\r\n\r\nTraducao PT: entendo  \r\nTraducao EN: understand  \r\nAudio nativo: `audio/A0-01/words/begrijp.native.nl.mp3`  \r\nAproximacao inicial PT: `be-RRAIP`  \r\nAproximacao inicial EN: `buh-GHRIPE`, with throat sound\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `begrijp`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: usar `g` de \"gato\".\r\n- EN: usar `g` de \"go\" ou transformar a palavra em ingles.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngr\r\ngrijp\r\nbegrijp\r\nik begrijp\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escolhe a palavra ouvida:\r\n\r\n```text\r\nA. begrijp\r\nB. betaal\r\nC. bedankt\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `begrijp` em audio e produz o som de garganta de forma compreensivel.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `het`\r\n\r\nTraducao PT: isso / o / a, dependendo do contexto  \r\nTraducao EN: it / the, depending on context  \r\nAudio nativo: `audio/A0-01/words/het.native.nl.mp3`  \r\nAproximacao inicial PT: `ut`  \r\nAproximacao inicial EN: `hut`, but weak\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `het`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: pronunciar como \"ret\".\r\n- EN: pronunciar sempre como `het` forte.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhet\r\nhet niet\r\nbegrijp het niet\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve:\r\n\r\n```text\r\nhet\r\n''t\r\n```\r\n\r\nE identifica que ambos podem representar `het`.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `het` mesmo quando soa reduzido.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `niet`\r\n\r\nTraducao PT: nao  \r\nTraducao EN: not  \r\nAudio nativo: `audio/A0-01/words/niet.native.nl.mp3`  \r\nAproximacao inicial PT: `niet`  \r\nAproximacao inicial EN: `neet`\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `niet`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer \"niete\".\r\n- EN: dizer \"night\".\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nniet\r\nhet niet\r\nik begrijp het niet\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escolhe:\r\n\r\n```text\r\nA. niet\r\nB. net\r\nC. met\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece e pronuncia `niet` com `t` final.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `kunt`\r\n\r\nTraducao PT: pode / consegue  \r\nTraducao EN: can  \r\nAudio nativo: `audio/A0-01/words/kunt.native.nl.mp3`  \r\nAproximacao inicial PT: `kant`, curto  \r\nAproximacao inicial EN: `kunt`, not like English \"can\"\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `kunt`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer \"cante\".\r\n- EN: trocar por \"can\".\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkunt\r\nkunt u\r\nkunt u mij\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nIdentificar `kunt` dentro de:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `kunt u` como bloco sonoro.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `u`\r\n\r\nTraducao PT: o senhor / a senhora / voce formal  \r\nTraducao EN: formal you  \r\nAudio nativo: `audio/A0-01/words/u.native.nl.mp3`  \r\nAproximacao inicial PT: `uu`, mas nao e o `u` portugues  \r\nAproximacao inicial EN: similar to German/French `u`/`ue`\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `u`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer `u` portugues.\r\n- EN: dizer `you`.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nu\r\nkunt u\r\nspreekt u\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nDistinguir:\r\n\r\n```text\r\nu\r\nik\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `u` e tenta produzir o som arredondado/frontal.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `mij`\r\n\r\nTraducao PT: me / mim  \r\nTraducao EN: me  \r\nAudio nativo: `audio/A0-01/words/mij.native.nl.mp3`  \r\nAproximacao inicial PT: `mei`  \r\nAproximacao inicial EN: close to `may`, not strong English `my`\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `mij`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer \"mi\".\r\n- EN: dizer \"my\" demasiado ingles.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmij\r\nkunt u mij\r\nkunt u mij helpen\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nEscolher entre:\r\n\r\n```text\r\nmij\r\nmijn\r\nmet\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `mij` e pronuncia como `mei`.\r\n\r\n### Palavra 9\r\n\r\nPalavra: `helpen`\r\n\r\nTraducao PT: ajudar  \r\nTraducao EN: help  \r\nAudio nativo: `audio/A0-01/words/helpen.native.nl.mp3`  \r\nAproximacao inicial PT: `HEL-puh`  \r\nAproximacao inicial EN: `HEL-puh`\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `helpen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: nao pronunciar o `h`.\r\n- EN: dizer \"helping\".\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhelpen\r\nmij helpen\r\nkunt u mij helpen\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nIdentificar `helpen` na frase:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece e produz `helpen` sem transformar em ingles.\r\n\r\n### Palavra 10\r\n\r\nPalavra: `herhalen`\r\n\r\nTraducao PT: repetir  \r\nTraducao EN: repeat  \r\nAudio nativo: `audio/A0-01/words/herhalen.native.nl.mp3`  \r\nAproximacao inicial PT: `her-HAA-luh`  \r\nAproximacao inicial EN: `hur-HAA-luh`\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `herhalen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: encurtar o `aa`.\r\n- EN: reduzir demais a silaba forte.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nherhalen\r\ndat herhalen\r\nkunt u dat herhalen\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nEscolher a palavra ouvida:\r\n\r\n```text\r\nA. herhalen\r\nB. helpen\r\nC. spreken\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `herhalen` e produz o `aa` longo.\r\n\r\n### Palavra 11\r\n\r\nPalavra: `langzaam`\r\n\r\nTraducao PT: devagar  \r\nTraducao EN: slowly  \r\nAudio nativo: `audio/A0-01/words/langzaam.native.nl.mp3`  \r\nAproximacao inicial PT: `LANG-zaam`  \r\nAproximacao inicial EN: `LAHNG-zaam`\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `langzaam`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer \"lan-gue-zaam\".\r\n- EN: dizer \"long-zam\".\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nlangzaam\r\nlangzaam spreken\r\nkunt u langzaam spreken\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nIdentificar se ouves:\r\n\r\n```text\r\nlangzaam\r\nsnel\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende que `langzaam` significa \"devagar\" e reconhece o som `ng`.\r\n\r\n### Palavra 12\r\n\r\nPalavra: `spreken`\r\n\r\nTraducao PT: falar  \r\nTraducao EN: speak  \r\nAudio nativo: `audio/A0-01/words/spreken.native.nl.mp3`  \r\nAproximacao inicial PT: `SPREI-kuh`  \r\nAproximacao inicial EN: `SPRAY-kuh`, cleaner than English\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `spreken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer \"espreken\".\r\n- EN: dizer \"speak-en\".\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nspreken\r\nlangzaam spreken\r\nkunt u langzaam spreken\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nEscolher a frase que contem `spreken`.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno diz `spreken` sem colocar `e` antes do `s`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"| Verbo | PT | EN | Forma usada |\r\n|---|---|---|---|\r\n| begrijpen | entender | to understand | ik begrijp |\r\n| helpen | ajudar | to help | helpen |\r\n| herhalen | repetir | to repeat | herhalen |\r\n| spreken | falar | to speak | spreken |\r\n\r\nNesta licao, o aluno aprende padroes de uso antes de estudar conjugacao completa."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"### Estrutura basica\r\n\r\nFrase simples:\r\n\r\n```text\r\nPessoa + verbo + resto da frase\r\n```\r\n\r\nExemplo:\r\n\r\n```text\r\nIk begrijp het niet.\r\nEu entendo isso nao.\r\nEu nao entendo.\r\n```\r\n\r\n### Negacao com `niet`\r\n\r\n`niet` significa \"nao\".\r\n\r\n```text\r\nIk begrijp het niet.\r\n```\r\n\r\nAqui, `niet` nega a ideia de entender.\r\n\r\n### Pedido educado com `Kunt u... ?`\r\n\r\n```text\r\nKunt u ... ?\r\n```\r\n\r\nSignifica:\r\n\r\n```text\r\nPode o senhor / a senhora ... ?\r\n```\r\n\r\nExemplos:\r\n\r\n```text\r\nKunt u mij helpen?\r\nKunt u dat herhalen?\r\nKunt u langzaam spreken?\r\n```\r\n\r\n### `u` formal\r\n\r\nUsar `u` com:\r\n\r\n- funcionarios\r\n- medicos\r\n- professores\r\n- pessoas desconhecidas\r\n- gemeente\r\n- clientes\r\n- supervisores"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis-com-template-completo', 7, '{"title":"Frases uteis com template completo","body":"### Frase 1\r\n\r\nFrase: `Sorry, ik begrijp het niet.`\r\n\r\nTraducao PT: Desculpe, nao entendo.  \r\nTraducao EN: Sorry, I do not understand.\r\nAudio nativo: `audio/A0-01/phrases/sorry-ik-begrijp-het-niet.native.nl.mp3`  \r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nSorry | ik begrijp | het niet\r\n```\r\n\r\nRitmo:\r\n\r\n```text\r\nSO-ri | ik be-GRIJP | het NIET\r\n```\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\nSO-ri | ik be-RRAIP | ut niet\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\nSOR-ree | ick buh-GHRIPE | hut neet\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nSorry, ik begrijp het niet.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nSorry, ik begrijp ''t niet.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nIk begrijp ''t niet.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Sorry, ik begrijp het niet.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: usar `g` portugues.\r\n- EN: pronunciar `begrijp` como ingles.\r\n- Ambos: separar palavra por palavra sem ritmo.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nik\r\nbegrijp\r\nhet niet\r\nik begrijp het niet\r\nsorry, ik begrijp het niet\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\nOuvir e repetir imediatamente:\r\n\r\n```text\r\nSorry, ik begrijp ''t niet.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nEscolher a frase correta:\r\n\r\n```text\r\nA. Sorry, ik begrijp het niet.\r\nB. Sorry, ik spreek Engels.\r\nC. Sorry, ik heb een afspraak.\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece a frase em forma lenta e natural e consegue repeti-la com ritmo compreensivel.\r\n\r\n### Frase 2\r\n\r\nFrase: `Kunt u mij helpen?`\r\n\r\nTraducao PT: Pode ajudar-me?  \r\nTraducao EN: Can you help me?\r\nAudio nativo: `audio/A0-01/phrases/kunt-u-mij-helpen.native.nl.mp3`  \r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nKunt u | mij helpen\r\n```\r\n\r\nRitmo:\r\n\r\n```text\r\nKUNT u | mij HEL-pen\r\n```\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\nkant uu | mei HEL-puh\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\nkunt uu | may HEL-puh\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nhelpen -> helpuh\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Kunt u mij helpen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer `u` portugues.\r\n- EN: dizer `you`.\r\n- Ambos: dizer `mij` como \"mi\".\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkunt u\r\nmij\r\nhelpen\r\nmij helpen\r\nkunt u mij helpen\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nIdentificar intencao:\r\n\r\n```text\r\nA. pedir ajuda\r\nB. pedir cafe\r\nC. pedir bilhete\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno usa a frase para pedir ajuda educadamente.\r\n\r\n### Frase 3\r\n\r\nFrase: `Kunt u dat herhalen?`\r\n\r\nTraducao PT: Pode repetir isso?  \r\nTraducao EN: Can you repeat that?\r\nAudio nativo: `audio/A0-01/phrases/kunt-u-dat-herhalen.native.nl.mp3`  \r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nKunt u | dat herhalen\r\n```\r\n\r\nRitmo:\r\n\r\n```text\r\nKUNT u | dat her-HAA-len\r\n```\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\nkant uu | dat her-HAA-luh\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\nkunt uu | dat hur-HAA-luh\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nKunt u dat herhalen?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nKunt u dat herhalen?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nherhalen -> herhaluh\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Kunt u dat herhalen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: encurtar o `aa`.\r\n- EN: reduzir demasiado a silaba forte.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ndat\r\nherhalen\r\ndat herhalen\r\nkunt u dat herhalen\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n```text\r\nKunt u dat herhalen?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nCompletar:\r\n\r\n```text\r\nKunt u dat h______?\r\n```\r\n\r\nResposta: `herhalen`\r\n\r\nCriterio de dominio:\r\n\r\nO aluno pede repeticao sem hesitar.\r\n\r\n### Frase 4\r\n\r\nFrase: `Kunt u langzaam spreken?`\r\n\r\nTraducao PT: Pode falar devagar?  \r\nTraducao EN: Can you speak slowly?\r\nAudio nativo: `audio/A0-01/phrases/kunt-u-langzaam-spreken.native.nl.mp3`  \r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nKunt u | langzaam spreken\r\n```\r\n\r\nRitmo:\r\n\r\n```text\r\nKUNT u | LANG-zaam SPREI-ken\r\n```\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\nkant uu | LANG-zaam SPREI-kuh\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\nkunt uu | LAHNG-zaam SPRAY-kuh\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nSem reducao obrigatoria para A0.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Kunt u langzaam spreken?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer `espreken`.\r\n- EN: dizer `speak-en`.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nlangzaam\r\nspreken\r\nlangzaam spreken\r\nkunt u langzaam spreken\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n```text\r\nKUNT u | LANG-zaam SPREI-ken?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nEscolher:\r\n\r\n```text\r\nA. A pessoa pede para falar devagar.\r\nB. A pessoa pede ajuda.\r\nC. A pessoa pergunta se fala ingles.\r\n```\r\n\r\nCriterio de dominio:\r\n\r\nO aluno usa esta frase quando a fala e demasiado rapida.\r\n\r\n### Frase 5\r\n\r\nFrase: `Spreekt u Engels?`\r\n\r\nTraducao PT: Fala ingles?  \r\nTraducao EN: Do you speak English?\r\nAudio nativo: `audio/A0-01/phrases/spreekt-u-engels.native.nl.mp3`  \r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nSpreekt u | Engels\r\n```\r\n\r\nRitmo:\r\n\r\n```text\r\nSPREEKT u | EN-gels\r\n```\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\nspreekt uu | EN-rruls\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\nspraykt uu | EN-ghuls\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nSpreekt u Engels?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nSpreekt u Engels?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nSem reducao obrigatoria para A0.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Spreekt u Engels?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer `espreekt`.\r\n- EN: dizer `English` em vez de `Engels`.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nspreekt\r\nspreekt u\r\nEngels\r\nSpreekt u Engels?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\nRepetir com entoacao de pergunta:\r\n\r\n```text\r\nSpreekt u Engels?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nIdentificar se a frase e pergunta ou afirmacao.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno pergunta por ingles de forma educada.\r\n\r\n### Frase 6\r\n\r\nFrase: `Ik spreek een beetje Nederlands.`\r\n\r\nTraducao PT: Falo um pouco de neerlandes.  \r\nTraducao EN: I speak a little Dutch.\r\nAudio nativo: `audio/A0-01/phrases/ik-spreek-een-beetje-nederlands.native.nl.mp3`  \r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk spreek | een beetje | Nederlands\r\n```\r\n\r\nRitmo:\r\n\r\n```text\r\nik SPREEK | een BEE-tje | NEE-der-lands\r\n```\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\nik SPREIK | un BEI-tchuh | NEI-der-lants\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\nick SPRAYK | un BAY-chuh | NAY-der-lahnts\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk spreek een beetje Nederlands.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk spreek ''n beetje Nederlands.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''n beetje\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik spreek een beetje Nederlands.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: pronunciar `een` como \"em\".\r\n- EN: transformar `Nederlands` em \"Netherlands\".\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nik spreek\r\neen beetje\r\nNederlands\r\nik spreek een beetje Nederlands\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n```text\r\nIk spreek ''n beetje Nederlands.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nCompletar:\r\n\r\n```text\r\nIk spreek ___ beetje Nederlands.\r\n```\r\n\r\nResposta: `een`\r\n\r\nCriterio de dominio:\r\n\r\nO aluno consegue dizer que fala um pouco de neerlandes sem traduzir palavra por palavra."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Focos desta licao:\r\n\r\n| Som | Exemplo | Guia PT |\r\n|---|---|---|\r\n| `g` | begrijp | `be-RRAIP` |\r\n| `u` | u | labios redondos, lingua a frente |\r\n| `ij` | mij | `mei` |\r\n| `-en` | helpen | `HÃ‰L-puh` |\r\n| `spr` | spreken | nao dizer `espreken` |"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Focos desta licao:\r\n\r\n| Som | Exemplo | Guia EN |\r\n|---|---|---|\r\n| `g` | begrijp | like Scottish `loch`, not `go` |\r\n| `u` | u | not `you`, closer to German/French `u` |\r\n| `ij` | mij | closer to `may` than `my` |\r\n| `-en` | helpen | weak final, not `helping` |\r\n| `Engels` | Engels | not English word `English` |"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### `g/ch` gutural\r\n\r\nUsado em:\r\n\r\n```text\r\nbegrijp\r\n```\r\n\r\nGarganta:\r\n\r\nA parte de tras da lingua aproxima-se do fundo da boca.\r\n\r\nAr:\r\n\r\nO ar passa com friccao.\r\n\r\nBoca:\r\n\r\nLigeiramente aberta.\r\n\r\nNao fazer:\r\n\r\n- `g` de gato\r\n- `g` de go\r\n\r\n### `u`\r\n\r\nUsado em:\r\n\r\n```text\r\nu\r\n```\r\n\r\nLabios:\r\n\r\nRedondos.\r\n\r\nLingua:\r\n\r\nA frente, como para dizer `i`.\r\n\r\nTreino:\r\n\r\n```text\r\ni -> arredondar labios -> u\r\n```\r\n\r\n### `ij`\r\n\r\nUsado em:\r\n\r\n```text\r\nmij\r\nbegrijp\r\n```\r\n\r\nA boca comeca mais aberta e fecha ligeiramente."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'posicao-da-boca', 11, '{"title":"Posicao da boca","body":"| Som | Boca |\r\n|---|---|\r\n| `u` | labios redondos |\r\n| `ij` | abertura media, movimento curto |\r\n| `aa` | boca mais aberta, som longo |\r\n| `ie` | boca mais fechada |"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'posicao-da-lingua', 12, '{"title":"Posicao da lingua","body":"| Som | Lingua |\r\n|---|---|\r\n| `g/ch` | parte de tras sobe para a garganta |\r\n| `u` | lingua a frente, labios redondos |\r\n| `ng` | parte de tras toca zona mole |\r\n| `t` final | ponta toca atras dos dentes |"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'sons-de-garganta', 13, '{"title":"Sons de garganta","body":"Treino:\r\n\r\n```text\r\ng\r\ngr\r\ngrijp\r\nbegrijp\r\nik begrijp\r\nik begrijp het niet\r\n```\r\n\r\nRegras:\r\n\r\n- nao deve magoar\r\n- nao vem da frente da boca\r\n- deve soar como friccao\r\n- deve ser reconhecivel"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 14, '{"title":"Ritmo e entoacao","body":"Frase afirmativa:\r\n\r\n```text\r\nSorry, ik begrijp het niet.\r\n```\r\n\r\nEntoacao desce no fim.\r\n\r\nPergunta educada:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nEntoacao sobe ligeiramente no fim.\r\n\r\nPergunta sim/nao:\r\n\r\n```text\r\nSpreekt u Engels?\r\n```\r\n\r\nEntoacao sobe no fim."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 15, '{"title":"Blocos sonoros","body":"```text\r\nSorry | ik begrijp | het niet\r\nKunt u | mij helpen\r\nKunt u | dat herhalen\r\nKunt u | langzaam spreken\r\nSpreekt u | Engels\r\nIk spreek | een beetje | Nederlands\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 16, '{"title":"Forma lenta, natural e reduzida","body":"| Escrita | Forma lenta | Forma natural | Forma reduzida |\r\n|---|---|---|---|\r\n| Ik begrijp het niet. | Ik begrijp het niet. | Ik begrijp ''t niet. | begrijp ''t niet |\r\n| Ik spreek een beetje Nederlands. | Ik spreek een beetje Nederlands. | Ik spreek ''n beetje Nederlands. | ''n beetje |\r\n| Kunt u mij helpen? | Kunt u mij helpen? | Kunt u mij helpen? | helpen -> helpuh |\r\n| Kunt u dat herhalen? | Kunt u dat herhalen? | Kunt u dat herhalen? | herhalen -> herhaluh |"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 17, '{"title":"Exercicios de repeticao","body":"```text\r\nik\r\nik begrijp\r\nik begrijp het niet\r\nsorry, ik begrijp het niet\r\n```\r\n\r\n```text\r\nkunt u\r\nkunt u mij\r\nkunt u mij helpen\r\n```\r\n\r\n```text\r\nlangzaam\r\nlangzaam spreken\r\nkunt u langzaam spreken\r\n```\r\n\r\n```text\r\nspreekt\r\nspreekt u\r\nspreekt u Engels?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 18, '{"title":"Exercicios de shadowing","body":"Instrucao:\r\n\r\nOuve a frase e repete imediatamente, copiando ritmo e entoacao.\r\n\r\nShadowing lento:\r\n\r\n```text\r\nSorry, ik begrijp het niet.\r\nKunt u mij helpen?\r\nKunt u dat herhalen?\r\nKunt u langzaam spreken?\r\n```\r\n\r\nShadowing natural:\r\n\r\n```text\r\nSorry, ik begrijp ''t niet.\r\nIk spreek ''n beetje Nederlands.\r\nSpreekt u Engels?\r\n```\r\n\r\nShadowing por dialogo:\r\n\r\n```text\r\nA: Goedemorgen.\r\nB: Sorry, ik begrijp het niet.\r\nA: Kunt u Nederlands spreken?\r\nB: Een beetje.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 19, '{"title":"Exercicios de audicao","body":"### 18.1 Palavra isolada\r\n\r\nAudio:\r\n\r\n```text\r\nhelpen\r\n```\r\n\r\nOpcoes:\r\n\r\n```text\r\nA. helpen\r\nB. herhalen\r\nC. spreken\r\n```\r\n\r\nResposta: A\r\n\r\n### 18.2 Frase lenta\r\n\r\nAudio:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nPergunta:\r\n\r\n```text\r\nO que a pessoa pede?\r\n```\r\n\r\nResposta: ajuda.\r\n\r\n### 18.3 Frase natural\r\n\r\nAudio:\r\n\r\n```text\r\nSorry, ik begrijp ''t niet.\r\n```\r\n\r\nEscolha:\r\n\r\n```text\r\nA. Sorry, ik begrijp het niet.\r\nB. Sorry, ik spreek Engels.\r\nC. Sorry, ik heb pijn.\r\n```\r\n\r\nResposta: A\r\n\r\n### 18.4 Mini dialogo\r\n\r\nAudio:\r\n\r\n```text\r\nA: Goedemorgen. Kan ik u helpen?\r\nB: Sorry, ik begrijp het niet.\r\nA: Spreekt u Engels?\r\nB: Een beetje.\r\n```\r\n\r\nPergunta:\r\n\r\n```text\r\nA pessoa B entende tudo?\r\n```\r\n\r\nResposta: nao.\r\n\r\n### 18.5 Identificacao de palavras-chave\r\n\r\nMarcar palavras ouvidas:\r\n\r\n```text\r\nsorry\r\nbegrijp\r\nhelpen\r\nEngels\r\n```\r\n\r\nDistratores:\r\n\r\n```text\r\nkoffie\r\ntrein\r\nhuis\r\n```\r\n\r\n### 18.6 Escolha multipla auditiva\r\n\r\nAudio:\r\n\r\n```text\r\nKunt u dat herhalen?\r\n```\r\n\r\nResposta correta:\r\n\r\n```text\r\nA. A pessoa quer que repitam.\r\n```\r\n\r\n### 18.7 Completar palavras ouvidas\r\n\r\nAudio:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\n```\r\n\r\nCompletar:\r\n\r\n```text\r\nKunt u ______ spreken?\r\n```\r\n\r\nResposta:\r\n\r\n```text\r\nlangzaam\r\n```\r\n\r\n### 18.8 Compreensao do dialogo\r\n\r\nDialogo:\r\n\r\n```text\r\nA: Heeft u een afspraak?\r\nB: Sorry, ik begrijp het niet.\r\nA: Heeft u een afspraak?\r\nB: Kunt u langzaam spreken?\r\n```\r\n\r\nPerguntas:\r\n\r\n1. A pessoa B entendeu a primeira?  \r\nResposta: nao.\r\n\r\n2. O que a pessoa B pediu?  \r\nResposta: para falar devagar.\r\n\r\n### 18.9 Shadowing auditivo\r\n\r\nAudio:\r\n\r\n```text\r\nIk spreek ''n beetje Nederlands.\r\n```\r\n\r\nTarefa:\r\n\r\nRepetir imediatamente.\r\n\r\n### 18.10 Teste final auditivo\r\n\r\nO aluno ouve:\r\n\r\n```text\r\n1. Sorry, ik begrijp het niet.\r\n2. Kunt u mij helpen?\r\n3. Kunt u dat herhalen?\r\n4. Kunt u langzaam spreken?\r\n5. Spreekt u Engels?\r\n```\r\n\r\nTarefas:\r\n\r\n- identificar cada frase\r\n- escolher traducao correta\r\n- repetir oralmente pelo menos 3\r\n\r\nCriterio:\r\n\r\nMinimo 4/5 corretas."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 20, '{"title":"Exercicios escritos","body":"Completar:\r\n\r\n```text\r\nIk begrijp het ____.\r\n```\r\n\r\nResposta:\r\n\r\n```text\r\nniet\r\n```\r\n\r\nOrdenar:\r\n\r\n```text\r\nu / mij / helpen / kunt\r\n```\r\n\r\nResposta:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nTraduzir:\r\n\r\n```text\r\nPode falar devagar?\r\n```\r\n\r\nResposta:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\n```\r\n\r\nEscolher:\r\n\r\n```text\r\nQual frase significa \"Pode repetir isso?\"\r\nA. Kunt u dat herhalen?\r\nB. Spreekt u Engels?\r\nC. Ik begrijp het niet.\r\n```\r\n\r\nResposta: A"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 21, '{"title":"Exercicios orais","body":"Dizer sem ler:\r\n\r\n```text\r\nSorry, ik begrijp het niet.\r\n```\r\n\r\nPedir ajuda:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nPedir repeticao:\r\n\r\n```text\r\nKunt u dat herhalen?\r\n```\r\n\r\nPedir fala lenta:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\n```\r\n\r\nResposta oral a uma situacao:\r\n\r\nInstrutor:\r\n\r\n```text\r\nHeeft u een afspraak?\r\n```\r\n\r\nAluno:\r\n\r\n```text\r\nSorry, ik begrijp het niet. Kunt u langzaam spreken?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 22, '{"title":"Mini dialogo realista","body":"Situacao: balcao da gemeente.\r\n\r\n```text\r\nMedewerker: Goedemorgen. Heeft u een afspraak?\r\nFuncionario: Bom dia. Tem marcacao?\r\n\r\nStudent: Sorry, ik begrijp het niet.\r\nAluno: Desculpe, nao entendo.\r\n\r\nMedewerker: Heeft u een afspraak?\r\nFuncionario: Tem marcacao?\r\n\r\nStudent: Kunt u langzaam spreken?\r\nAluno: Pode falar devagar?\r\n\r\nMedewerker: Ja, natuurlijk. Heeft u een afspraak?\r\nFuncionario: Sim, claro. Tem marcacao?\r\n\r\nStudent: Ja. Ik heb een afspraak.\r\nAluno: Sim. Tenho uma marcacao.\r\n```\r\n\r\nFoco:\r\n\r\nO aluno nao precisa entender tudo. Precisa saber controlar a situacao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 23, '{"title":"Roleplay","body":"### Roleplay 1 â€” Loja\r\n\r\nFuncionario:\r\n\r\n```text\r\nGoedemiddag. Kan ik u helpen?\r\n```\r\n\r\nAluno:\r\n\r\n```text\r\nSorry, ik begrijp het niet.\r\n```\r\n\r\nFuncionario:\r\n\r\n```text\r\nKan ik u helpen?\r\n```\r\n\r\nAluno:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\n```\r\n\r\nFuncionario:\r\n\r\n```text\r\nJa. Heeft u hulp nodig?\r\n```\r\n\r\nAluno:\r\n\r\n```text\r\nJa, kunt u mij helpen?\r\n```\r\n\r\n### Roleplay 2 â€” Gemeente\r\n\r\nFuncionario:\r\n\r\n```text\r\nHeeft u een afspraak?\r\n```\r\n\r\nAluno:\r\n\r\n```text\r\nSorry, ik begrijp het niet. Kunt u dat herhalen?\r\n```\r\n\r\nFuncionario:\r\n\r\n```text\r\nHeeft u een afspraak?\r\n```\r\n\r\nAluno:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\n```\r\n\r\n### Roleplay 3 â€” Farmacia\r\n\r\nFuncionario:\r\n\r\n```text\r\nWat heeft u nodig?\r\n```\r\n\r\nAluno:\r\n\r\n```text\r\nSorry, ik begrijp het niet. Spreekt u Engels?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 24, '{"title":"Erros comuns","body":"Erro:\r\n\r\n```text\r\nNiet Nederlands.\r\n```\r\n\r\nMelhor:\r\n\r\n```text\r\nIk begrijp het niet.\r\n```\r\n\r\nErro:\r\n\r\n```text\r\nHelp mij.\r\n```\r\n\r\nMelhor:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nErro:\r\n\r\n```text\r\nbegrijp com g portugues\r\n```\r\n\r\nMelhor:\r\n\r\n```text\r\nbe-RRAIP\r\n```\r\n\r\nErro:\r\n\r\n```text\r\nu = you\r\n```\r\n\r\nMelhor:\r\n\r\n```text\r\nu com labios redondos e lingua a frente\r\n```\r\n\r\nErro:\r\n\r\n```text\r\nKunt / u / mij / helpen\r\n```\r\n\r\nMelhor:\r\n\r\n```text\r\nKunt u | mij helpen\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 25, '{"title":"Quiz","body":"1. O que significa `Ik begrijp het niet`?\r\n\r\n```text\r\nA. Nao entendo.\r\nB. Quero pagar.\r\nC. Tenho uma marcacao.\r\n```\r\n\r\nResposta: A\r\n\r\n2. Como se diz \"Pode ajudar-me?\"\r\n\r\n```text\r\nA. Kunt u mij helpen?\r\nB. Kunt u dat herhalen?\r\nC. Spreekt u Engels?\r\n```\r\n\r\nResposta: A\r\n\r\n3. O que significa `langzaam`?\r\n\r\n```text\r\nA. rapido\r\nB. devagar\r\nC. amanha\r\n```\r\n\r\nResposta: B\r\n\r\n4. Qual e a frase para pedir repeticao?\r\n\r\n```text\r\nA. Kunt u dat herhalen?\r\nB. Ik spreek Portugees.\r\nC. Ik heb pijn.\r\n```\r\n\r\nResposta: A\r\n\r\n5. Qual frase pergunta se a pessoa fala ingles?\r\n\r\n```text\r\nA. Spreekt u Engels?\r\nB. Kunt u mij helpen?\r\nC. Ik begrijp het niet.\r\n```\r\n\r\nResposta: A\r\n\r\n6. Em fala natural, `het` pode soar como:\r\n\r\n```text\r\nA. ''t\r\nB. huis\r\nC. goed\r\n```\r\n\r\nResposta: A\r\n\r\n7. O som `g` em `begrijp` vem principalmente:\r\n\r\n```text\r\nA. da garganta\r\nB. dos labios\r\nC. dos dentes da frente\r\n```\r\n\r\nResposta: A\r\n\r\nCriterio:\r\n\r\n```text\r\n6/7 respostas corretas\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 26, '{"title":"Flashcards","body":"Frente:\r\n\r\n```text\r\nSorry, ik begrijp het niet.\r\n```\r\n\r\nVerso:\r\n\r\n```text\r\nDesculpe, nao entendo.\r\n```\r\n\r\nFrente:\r\n\r\n```text\r\nKunt u mij helpen?\r\n```\r\n\r\nVerso:\r\n\r\n```text\r\nPode ajudar-me?\r\n```\r\n\r\nFrente:\r\n\r\n```text\r\nKunt u dat herhalen?\r\n```\r\n\r\nVerso:\r\n\r\n```text\r\nPode repetir isso?\r\n```\r\n\r\nFrente:\r\n\r\n```text\r\nKunt u langzaam spreken?\r\n```\r\n\r\nVerso:\r\n\r\n```text\r\nPode falar devagar?\r\n```\r\n\r\nFrente:\r\n\r\n```text\r\nSpreekt u Engels?\r\n```\r\n\r\nVerso:\r\n\r\n```text\r\nFala ingles?\r\n```\r\n\r\nFrente:\r\n\r\n```text\r\nIk spreek een beetje Nederlands.\r\n```\r\n\r\nVerso:\r\n\r\n```text\r\nFalo um pouco de neerlandes.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-da-licao', 27, '{"title":"Teste final da licao","body":"### Parte 1 â€” Audicao\r\n\r\nO aluno ouve 5 frases e identifica pelo menos 4:\r\n\r\n```text\r\nSorry, ik begrijp het niet.\r\nKunt u mij helpen?\r\nKunt u dat herhalen?\r\nKunt u langzaam spreken?\r\nSpreekt u Engels?\r\n```\r\n\r\n### Parte 2 â€” Producao oral\r\n\r\nO aluno diz sem ler:\r\n\r\n```text\r\nSorry, ik begrijp het niet.\r\nKunt u langzaam spreken?\r\n```\r\n\r\n### Parte 3 â€” Roleplay\r\n\r\nO aluno participa num mini dialogo e consegue pedir repeticao ou ajuda.\r\n\r\n### Parte 4 â€” Escrita\r\n\r\nCompletar:\r\n\r\n```text\r\nIk begrijp het ____.\r\nKunt u mij ____?\r\nKunt u langzaam ____?\r\n```\r\n\r\nRespostas:\r\n\r\n```text\r\nniet\r\nhelpen\r\nspreken\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 28, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer 10 palavras principais\r\n- pronunciar pelo menos 6 palavras de forma compreensivel\r\n- distinguir forma lenta e natural de 3 frases\r\n- reconhecer `het` quando soa como `''t`\r\n- usar `Kunt u... ?` para pedir ajuda\r\n- pedir para repetir\r\n- pedir para falar devagar\r\n- perguntar se a pessoa fala ingles\r\n- fazer o roleplay de loja ou gemeente\r\n- acertar pelo menos 6/7 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo final\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nSorry, ik begrijp het niet. Kunt u langzaam spreken?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'sorry', 'desculpe', 'sorry', 'Na palavra `sorry`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 1 from lessons l where l.code = 'A0-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'ik', 'eu', 'I', 'Na palavra `ik`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 2 from lessons l where l.code = 'A0-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'begrijp', 'entendo', 'understand', 'Na palavra `begrijp`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 3 from lessons l where l.code = 'A0-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'het', 'isso / o / a, dependendo do contexto', 'it / the, depending on context', 'Na palavra `het`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 4 from lessons l where l.code = 'A0-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'niet', 'nao', 'not', 'Na palavra `niet`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 5 from lessons l where l.code = 'A0-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'kunt', 'pode / consegue', 'can', 'Na palavra `kunt`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 6 from lessons l where l.code = 'A0-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'u', 'o senhor / a senhora / voce formal', 'formal you', 'Na palavra `u`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 7 from lessons l where l.code = 'A0-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'mij', 'me / mim', 'me', 'Na palavra `mij`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 8 from lessons l where l.code = 'A0-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'helpen', 'ajudar', 'help', 'Na palavra `helpen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 9 from lessons l where l.code = 'A0-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'herhalen', 'repetir', 'repeat', 'Na palavra `herhalen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 10 from lessons l where l.code = 'A0-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'langzaam', 'devagar', 'slowly', 'Na palavra `langzaam`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 11 from lessons l where l.code = 'A0-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'spreken', 'falar', 'speak', 'Na palavra `spreken`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', '', 12 from lessons l where l.code = 'A0-01';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Sorry, ik begrijp het niet.', 'Desculpe, nao entendo.', 'Sorry, I do not understand.', 'Sorry | ik begrijp | het niet', 'Sorry, ik begrijp het niet.', 'Sorry, ik begrijp ''t niet.', 'Ik begrijp ''t niet.', 'Na frase `Sorry, ik begrijp het niet.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'A0-01';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Kunt u mij helpen?', 'Pode ajudar-me?', 'Can you help me?', 'Kunt u | mij helpen', 'Kunt u mij helpen?', 'Kunt u mij helpen?', 'helpen -> helpuh', 'Na frase `Kunt u mij helpen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'A0-01';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Kunt u dat herhalen?', 'Pode repetir isso?', 'Can you repeat that?', 'Kunt u | dat herhalen', 'Kunt u dat herhalen?', 'Kunt u dat herhalen?', 'herhalen -> herhaluh', 'Na frase `Kunt u dat herhalen?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'A0-01';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Kunt u langzaam spreken?', 'Pode falar devagar?', 'Can you speak slowly?', 'Kunt u | langzaam spreken', 'Kunt u langzaam spreken?', 'Kunt u langzaam spreken?', 'Sem reducao obrigatoria para A0.', 'Na frase `Kunt u langzaam spreken?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'A0-01';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Spreekt u Engels?', 'Fala ingles?', 'Do you speak English?', 'Spreekt u | Engels', 'Spreekt u Engels?', 'Spreekt u Engels?', 'Sem reducao obrigatoria para A0.', 'Na frase `Spreekt u Engels?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 5 from lessons l where l.code = 'A0-01';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik spreek een beetje Nederlands.', 'Falo um pouco de neerlandes.', 'I speak a little Dutch.', 'Ik spreek | een beetje | Nederlands', 'Ik spreek een beetje Nederlands.', 'Ik spreek ''n beetje Nederlands.', '''n beetje', 'Na frase `Ik spreek een beetje Nederlands.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 6 from lessons l where l.code = 'A0-01';
