select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"`spellen` - soletrar; `horen` - ouvir; `zeggen` - dizer."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-02';
