insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A0-03', 'Pronuncia essencial', 'reconhecer g/ch, sch, ui, ij/ei, oe e u', 2, 'published', 35
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A0'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar e ajustar a fala ate se aproximar do neerlandes natural."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Mesmo conhecendo palavras, o aluno pode nao ser entendido se pronunciar sons neerlandeses como portugues ou ingles. Esta licao treina sons que aparecem constantemente.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nPessoa: Spreekt u Nederlands?\r\nAluno: Ik spreek een beetje Nederlands.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- reconhecer g/ch, sch, ui, ij/ei, oe e u\r\n- produzir versoes compreensiveis\r\n- perceber fala lenta e natural\r\n- evitar erros PT/EN\r\n- fazer shadowing tecnico\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk spreek een beetje Nederlands. Hoe zegt u dat?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk spreek een beetje Nederlands.\r\nHoe zegt u dat?\r\nLuister en herhaal.\r\nIk hoor het verschil.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `graag`\r\n\r\nTraducao PT: com gosto / de bom grado  \r\nTraducao EN: gladly  \r\nAudio nativo: `audio/A0-03/words/graag.native.nl.mp3`  \r\nAproximacao inicial PT: `rraakh`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `graag`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: usar g portugues.\r\n- EN: usar g de go.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngraag\r\ngraag em bloco\r\ngraag em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `graag` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `graag` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `goed`\r\n\r\nTraducao PT: bom / bem  \r\nTraducao EN: good / well  \r\nAudio nativo: `audio/A0-03/words/goed.native.nl.mp3`  \r\nAproximacao inicial PT: `rrut`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `goed`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `oe`, arredonde os labios como um `u` fechado, mantendo o som limpo e curto quando o audio nativo assim o mostrar. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer gude.\r\n- EN: dizer good.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ngoed\r\ngoed em bloco\r\ngoed em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `goed` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `goed` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `huis`\r\n\r\nTraducao PT: casa  \r\nTraducao EN: house  \r\nAudio nativo: `audio/A0-03/words/huis.native.nl.mp3`  \r\nAproximacao inicial PT: `ui` native-audio-first  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `huis`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer raus.\r\n- EN: dizer house.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhuis\r\nhuis em bloco\r\nhuis em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `huis` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `huis` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `mijn`\r\n\r\nTraducao PT: meu/minha  \r\nTraducao EN: my  \r\nAudio nativo: `audio/A0-03/words/mijn.native.nl.mp3`  \r\nAproximacao inicial PT: `mein`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `mijn`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer min.\r\n- EN: dizer mine forte.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nmijn\r\nmijn em bloco\r\nmijn em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `mijn` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `mijn` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `spreek`\r\n\r\nTraducao PT: falo  \r\nTraducao EN: speak  \r\nAudio nativo: `audio/A0-03/words/spreek.native.nl.mp3`  \r\nAproximacao inicial PT: `spreik`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `spreek`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer espreek.\r\n- EN: dizer speak ingles.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nspreek\r\nspreek em bloco\r\nspreek em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `spreek` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `spreek` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `Nederlands`\r\n\r\nTraducao PT: neerlandes  \r\nTraducao EN: Dutch  \r\nAudio nativo: `audio/A0-03/words/nederlands.native.nl.mp3`  \r\nAproximacao inicial PT: `NEI-der-lants`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `Nederlands`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer nederlandese.\r\n- EN: dizer Netherlands.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nNederlands\r\nNederlands em bloco\r\nNederlands em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `Nederlands` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `Nederlands` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-03';
