insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A0-08', 'Revisao A0', 'reconhecer vocabulario essencial em audio lento e natural', 7, 'published', 35
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A0'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar e ajustar a fala ate se aproximar do neerlandes natural."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Esta licao prepara o aluno para revisao integrada de ajuda, alfabeto, pronuncia, cumprimentos, numeros, datas e sobrevivencia. O foco e transformar linguagem basica em acao real, com audicao, pronuncia fisica, repeticao, shadowing e resposta oral.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nPessoa nativa fala em ritmo natural.\r\nAluno identifica palavras-chave e responde: Goedemorgen. Sorry, ik begrijp het niet. Kunt u dat spellen?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- reconhecer vocabulario essencial em audio lento e natural\r\n- usar frases praticas em contexto real\r\n- treinar pronuncia pelo audio nativo\r\n- fazer shadowing por blocos\r\n- responder oralmente sem bloquear\r\n- completar exercicios escritos e auditivos\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nGoedemorgen. Sorry, ik begrijp het niet. Kunt u dat spellen?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nGoedemorgen, ik heb een afspraak.\r\nKunt u dat spellen?\r\nMijn nummer is zevenentwintig.\r\nIk spreek een beetje Nederlands.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-08';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `begrijp`\r\n\r\nTraducao PT: entendo  \r\nTraducao EN: understand  \r\nAudio nativo: `audio/A0-08/words/begrijp.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `begrijp`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbegrijp\r\nbegrijp em bloco\r\nbegrijp em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `begrijp` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `begrijp` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `spellen`\r\n\r\nTraducao PT: soletrar  \r\nTraducao EN: spell  \r\nAudio nativo: `audio/A0-08/words/spellen.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `spellen`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nspellen\r\nspellen em bloco\r\nspellen em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `spellen` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `spellen` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `nummer`\r\n\r\nTraducao PT: numero  \r\nTraducao EN: number  \r\nAudio nativo: `audio/A0-08/words/nummer.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `nummer`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nnummer\r\nnummer em bloco\r\nnummer em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `nummer` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `nummer` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `datum`\r\n\r\nTraducao PT: data  \r\nTraducao EN: date  \r\nAudio nativo: `audio/A0-08/words/datum.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `datum`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ndatum\r\ndatum em bloco\r\ndatum em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `datum` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `datum` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `afspraak`\r\n\r\nTraducao PT: marcacao  \r\nTraducao EN: appointment  \r\nAudio nativo: `audio/A0-08/words/afspraak.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `afspraak`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nafspraak\r\nafspraak em bloco\r\nafspraak em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `afspraak` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `afspraak` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `Nederlands`\r\n\r\nTraducao PT: neerlandes  \r\nTraducao EN: Dutch  \r\nAudio nativo: `audio/A0-08/words/nederlands.native.nl.mp3`  \r\nAproximacao inicial PT: apoio inicial; ouvir audio nativo primeiro  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `Nederlands`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: ler como portugues e acrescentar vogal final.\r\n- EN: usar pronuncia inglesa automatica.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nNederlands\r\nNederlands em bloco\r\nNederlands em frase curta\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve tres opcoes com uma palavra-alvo. Deve identificar `Nederlands` sem ler a transcricao. Depois ouve a mesma palavra dentro de uma frase natural.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `Nederlands` em audio nativo e consegue produzir uma versao compreensivel sem tratar a aproximacao escrita como pronuncia final."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A0-08';
