insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A1-01', 'Apresentar-se', 'dizer nome e origem', 0, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar a lingua em situacoes reais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"O aluno precisa apresentar-se no trabalho, numa escola, num curso, numa entrevista simples, no medico ou ao falar com vizinhos. A meta e sair de respostas soltas e construir uma apresentacao curta.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nCollega: Wie bent u?\r\nAluno: Ik ben Henrique. Ik kom uit Portugal. Ik spreek Portugees en Engels.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- dizer nome e origem\r\n- dizer que linguas fala\r\n- perguntar o nome de outra pessoa\r\n- usar `ik ben` e `ik kom uit`\r\n- responder em contexto formal e informal\r\n- fazer uma apresentacao oral de 20 segundos\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk ben Henrique. Ik kom uit Portugal. Ik woon in Nederland.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk ben Henrique.\r\nMijn naam is Henrique.\r\nIk kom uit Portugal.\r\nIk woon in Nederland.\r\nWelke taal spreekt u?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `naam`\r\n\r\nTraducao PT: nome  \r\nTraducao EN: name  \r\nAudio nativo: `audio/A1-01/words/naam.native.nl.mp3`  \r\nAproximacao inicial PT: `naam`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `naam`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer name em portugues/ingles.\r\n- EN: usar ditongo ingles.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn naam is Henrique.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nnaam\r\nnaam em bloco\r\nMijn naam is Henrique.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `naam` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `naam` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `voornaam`\r\n\r\nTraducao PT: primeiro nome  \r\nTraducao EN: first name  \r\nAudio nativo: `audio/A1-01/words/voornaam.native.nl.mp3`  \r\nAproximacao inicial PT: `VOOR-naam`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `voornaam`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: cortar as vogais longas.\r\n- EN: dizer for-name.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn voornaam is Henrique.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvoornaam\r\nvoornaam em bloco\r\nMijn voornaam is Henrique.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `voornaam` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `voornaam` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `achternaam`\r\n\r\nTraducao PT: apelido/sobrenome  \r\nTraducao EN: surname  \r\nAudio nativo: `audio/A1-01/words/achternaam.native.nl.mp3`  \r\nAproximacao inicial PT: `AKH-ter-naam`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `achternaam`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: usar ch portugues.\r\n- EN: usar ch de church.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nMijn achternaam is Silva.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nachternaam\r\nachternaam em bloco\r\nMijn achternaam is Silva.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `achternaam` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `achternaam` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `land`\r\n\r\nTraducao PT: pais  \r\nTraducao EN: country  \r\nAudio nativo: `audio/A1-01/words/land.native.nl.mp3`  \r\nAproximacao inicial PT: `lant`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `land`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer lande.\r\n- EN: alongar como land ingles.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nPortugal is mijn land.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nland\r\nland em bloco\r\nPortugal is mijn land.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `land` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `land` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `taal`\r\n\r\nTraducao PT: lingua/idioma  \r\nTraducao EN: language  \r\nAudio nativo: `audio/A1-01/words/taal.native.nl.mp3`  \r\nAproximacao inicial PT: `taal`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `taal`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer tala.\r\n- EN: usar vowel de tall.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWelke taal spreekt u?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntaal\r\ntaal em bloco\r\nWelke taal spreekt u?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `taal` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `taal` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `Portugees`\r\n\r\nTraducao PT: portugues  \r\nTraducao EN: Portuguese  \r\nAudio nativo: `audio/A1-01/words/portugees.native.nl.mp3`  \r\nAproximacao inicial PT: `por-tu-GEES`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `Portugees`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer portugues como em PT.\r\n- EN: usar Portuguese ingles.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk spreek Portugees.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nPortugees\r\nPortugees em bloco\r\nIk spreek Portugees.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `Portugees` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `Portugees` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `Engels`\r\n\r\nTraducao PT: ingles  \r\nTraducao EN: English  \r\nAudio nativo: `audio/A1-01/words/engels.native.nl.mp3`  \r\nAproximacao inicial PT: `EN-ghuls`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `Engels`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer ingeles.\r\n- EN: dizer English.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk spreek Engels.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nEngels\r\nEngels em bloco\r\nIk spreek Engels.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `Engels` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `Engels` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `Nederland`\r\n\r\nTraducao PT: Holanda/Paises Baixos  \r\nTraducao EN: Netherlands  \r\nAudio nativo: `audio/A1-01/words/nederland.native.nl.mp3`  \r\nAproximacao inicial PT: `NEI-der-lant`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `Nederland`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer nederlande.\r\n- EN: dizer Netherlands.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk woon in Nederland.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nNederland\r\nNederland em bloco\r\nIk woon in Nederland.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `Nederland` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `Nederland` em audio nativo e usa a palavra numa resposta A1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'verbos-principais', 5, '{"title":"Verbos principais","body":"Os verbos desta licao aparecem em frases reais. O aluno treina primeiro reconhecimento auditivo, depois producao oral, e so depois variacao escrita."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'gramatica-necessaria', 6, '{"title":"Gramatica necessaria","body":"Estruturas A1: `Ik ben + naam`, `Ik kom uit + land`, `Ik woon in + plaats`, `Ik spreek + taal`. O verbo fica na segunda posicao em frases simples: `Ik ben Henrique`, `Ik woon in Rotterdam`."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'frases-uteis', 7, '{"title":"Frases uteis","body":"### Frase 1\r\n\r\nFrase: `Ik ben Henrique.`\r\n\r\nTraducao PT: Eu sou o Henrique.  \r\nTraducao EN: I am Henrique.  \r\nAudio nativo: `audio/A1-01/phrases/ik-ben-henrique.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nApresentacao pessoal.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk ben / Henrique.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk ben Henrique.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk ben Henrique.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Ben Henrique.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik ben Henrique.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer ique bene.\r\n- EN: usar ritmo ingles.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk ben / Henrique.\r\nIk ben Henrique.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 2\r\n\r\nFrase: `Mijn naam is Henrique.`\r\n\r\nTraducao PT: O meu nome e Henrique.  \r\nTraducao EN: My name is Henrique.  \r\nAudio nativo: `audio/A1-01/phrases/mijn-naam-is-henrique.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nQuando pedem o nome.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nMijn naam / is Henrique.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nMijn naam is Henrique.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nMijn naam is Henrique.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nM''n naam is Henrique.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Mijn naam is Henrique.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer min.\r\n- EN: dizer mine/name.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nMijn naam / is Henrique.\r\nMijn naam is Henrique.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 3\r\n\r\nFrase: `Ik kom uit Portugal.`\r\n\r\nTraducao PT: Venho de Portugal.  \r\nTraducao EN: I come from Portugal.  \r\nAudio nativo: `audio/A1-01/phrases/ik-kom-uit-portugal.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nDizer pais de origem.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk kom / uit Portugal.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk kom uit Portugal.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk kom uit Portugal.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Kom uit Portugal.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik kom uit Portugal.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer uit como u-it.\r\n- EN: dizer out.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk kom / uit Portugal.\r\nIk kom uit Portugal.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 4\r\n\r\nFrase: `Ik woon in Nederland.`\r\n\r\nTraducao PT: Vivo nos Paises Baixos.  \r\nTraducao EN: I live in the Netherlands.  \r\nAudio nativo: `audio/A1-01/phrases/ik-woon-in-nederland.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nDizer onde vive.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nIk woon / in Nederland.\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nIk woon in Nederland.\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nIk woon in Nederland.\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\n''k Woon in Nederland.\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Ik woon in Nederland.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer von.\r\n- EN: dizer Netherlands.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nIk woon / in Nederland.\r\nIk woon in Nederland.\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler.\r\n\r\n### Frase 5\r\n\r\nFrase: `Welke taal spreekt u?`\r\n\r\nTraducao PT: Que lingua fala?  \r\nTraducao EN: Which language do you speak?  \r\nAudio nativo: `audio/A1-01/phrases/welke-taal-spreekt-u.native.nl.mp3`\r\n\r\nSituacao de uso:\r\n\r\nPerguntar lingua em contexto formal.\r\n\r\nBlocos sonoros:\r\n\r\n```text\r\nWelke taal / spreekt u?\r\n```\r\n\r\nRitmo:\r\n\r\nA frase deve ser treinada em tres etapas: blocos lentos, frase natural e resposta dentro de dialogo. A palavra com informacao nova recebe mais energia.\r\n\r\nAproximacao inicial PT:\r\n\r\n```text\r\napoio inicial apenas; confirmar sempre com audio nativo\r\n```\r\n\r\nAproximacao inicial EN:\r\n\r\n```text\r\ninitial support only; always confirm with native audio\r\n```\r\n\r\nForma lenta:\r\n\r\n```text\r\nWelke taal spreekt u?\r\n```\r\n\r\nForma natural:\r\n\r\n```text\r\nWelke taal spreek-tu?\r\n```\r\n\r\nForma reduzida:\r\n\r\n```text\r\nWelke taal spreekt u?\r\n```\r\n\r\nExplicacao fisica:\r\n\r\nNa frase `Welke taal spreekt u?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer espreeckt.\r\n- EN: usar you forte.\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nWelke taal / spreekt u?\r\nWelke taal spreekt u?\r\n```\r\n\r\nExercicio de shadowing:\r\n\r\n1. Ouvir o audio lento duas vezes.\r\n2. Repetir por blocos.\r\n3. Ouvir a forma natural tres vezes.\r\n4. Falar junto com o audio nativo.\r\n5. Responder oralmente com informacao propria.\r\n6. Gravar e comparar ritmo, vogais, consoantes finais e reducoes.\r\n\r\nExercicio de audicao:\r\n\r\nO aluno escuta tres versoes: lenta, natural e em mini dialogo. Deve identificar palavras-chave, escolher a traducao correta e completar uma palavra em falta.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno entende a frase em audio natural e consegue adapta-la com informacao propria sem ler."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-pt-nl', 8, '{"title":"Aproximacao inicial PT -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao adicionar vogal final em palavras terminadas por consoante.\r\n- Pronunciar `h` quando existir.\r\n- Tratar `g/ch/sch` como som fisico de garganta, nao como letra portuguesa.\r\n- Manter vogais longas e curtas diferentes.\r\n- Usar a aproximacao escrita apenas para arrancar, nunca como pronuncia correta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'aproximacao-inicial-en-nl', 9, '{"title":"Aproximacao inicial EN -> NL","body":"Esta seccao e apenas apoio inicial. O aluno deve sempre voltar ao audio nativo.\r\n\r\n- Nao substituir sons neerlandeses por sons ingleses parecidos.\r\n- Evitar ritmo ingles em frases neerlandesas.\r\n- Confirmar `u`, `ij/ei`, `ui`, `oe`, `aa`, `ee` com audio nativo.\r\n- Nao transformar palavras neerlandesas em cognatos ingleses."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'explicacao-fisica-dos-sons-dificeis', 10, '{"title":"Explicacao fisica dos sons dificeis","body":"### Finais de palavra\r\n\r\nFechar consoantes sem vogal extra. Isto e essencial para o aluno ser entendido.\r\n\r\n### Vogais longas e curtas\r\n\r\nOuvir o contraste no audio antes de repetir. A duracao muda naturalidade e, as vezes, significado.\r\n\r\n### Sons de garganta\r\n\r\n`g/ch/sch` usam friccao atras da boca. A garganta trabalha de forma leve, sem dor.\r\n\r\n### Reducoes naturais\r\n\r\n`het` pode soar como `''t`; `een` pode soar como `''n`; `ik` pode reduzir para `''k`. O aluno deve reconhecer antes de tentar usar."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'boca-lingua-e-garganta', 11, '{"title":"Boca, lingua e garganta","body":"- Boca: relaxada, movimentos controlados, sem exagerar abertura.\r\n- Lingua: toca atras dos dentes em `t/d/n/l`; sobe para vogais fechadas.\r\n- Labios: arredondam em `u/oe/ui`.\r\n- Garganta: ativa apenas em `g/ch/sch`, com friccao leve."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'ritmo-e-entoacao', 12, '{"title":"Ritmo e entoacao","body":"O aluno treina palavra isolada, bloco sonoro, frase lenta, frase natural e resposta em dialogo. Perguntas sobem ligeiramente; respostas descem e fecham."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'blocos-sonoros', 13, '{"title":"Blocos sonoros","body":"```text\r\nIk ben / Henrique.\r\nMijn naam / is Henrique.\r\nIk kom / uit Portugal.\r\nIk woon / in Nederland.\r\nWelke taal / spreekt u?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'forma-lenta-natural-e-reduzida', 14, '{"title":"Forma lenta, natural e reduzida","body":"```text\r\nLenta: articular cada palavra claramente.\r\nNatural: juntar blocos frequentes.\r\nReduzida: reconhecer ''t, ''n, ''k e ligacoes quando aparecerem no audio.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-repeticao', 15, '{"title":"Exercicios de repeticao","body":"1. Repetir cada palavra isolada.\r\n2. Repetir cada palavra dentro do exemplo.\r\n3. Repetir cada frase lenta.\r\n4. Repetir cada frase por blocos.\r\n5. Repetir a frase final completa.\r\n\r\n```text\r\nIk ben Henrique. Ik kom uit Portugal. Ik woon in Nederland.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-shadowing', 16, '{"title":"Exercicios de shadowing","body":"1. Ouvir palavra isolada.\r\n2. Repetir depois do audio.\r\n3. Ouvir frase lenta.\r\n4. Repetir por blocos.\r\n5. Ouvir frase natural.\r\n6. Falar junto com o audio.\r\n7. Responder com informacao propria.\r\n8. Gravar e comparar com o audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-de-audicao', 17, '{"title":"Exercicios de audicao","body":"### Palavra isolada\r\n\r\nIdentificar vocabulario principal sem transcricao.\r\n\r\n### Frase lenta\r\n\r\nSelecionar a frase correta entre tres opcoes.\r\n\r\n### Frase natural\r\n\r\nMarcar palavras-chave e notar reducoes.\r\n\r\n### Mini dialogo\r\n\r\nResponder perguntas de compreensao.\r\n\r\n### Escolha multipla auditiva\r\n\r\nO aluno ouve uma frase e escolhe a intencao: apresentar-se, pedir ajuda, confirmar informacao, comprar, falar de familia ou pedir direcao.\r\n\r\n### Completar palavras ouvidas\r\n\r\nCompletar letras em falta depois de ouvir audio nativo."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-escritos', 18, '{"title":"Exercicios escritos","body":"1. Completar frases com vocabulario principal.\r\n2. Ligar frase a traducao PT e EN.\r\n3. Ordenar palavras para formar uma frase neerlandesa.\r\n4. Substituir uma informacao por dados pessoais.\r\n5. Escrever uma resposta curta para uma situacao real."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'exercicios-orais', 19, '{"title":"Exercicios orais","body":"1. Repeticao guiada.\r\n2. Repeticao por blocos.\r\n3. Leitura em voz alta depois de ouvir.\r\n4. Resposta oral sem ler.\r\n5. Pergunta e resposta com dados proprios.\r\n6. Mini roleplay."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'mini-dialogo-realista', 20, '{"title":"Mini dialogo realista","body":"```text\r\nPessoa: Goedemorgen.\r\nAluno: Goedemorgen.\r\nPessoa: Ik ben Henrique.\r\nAluno: Sorry, kunt u dat herhalen?\r\nPessoa: Mijn naam is Henrique.\r\nAluno: Dank u wel. Ik ben Henrique. Ik kom uit Portugal. Ik woon in Nederland.\r\n```\r\n\r\nCompreensao:\r\n\r\n- Qual foi a primeira pergunta ou frase principal?\r\n- Que informacao o aluno conseguiu dar?\r\n- Que frase foi usada para manter a conversa quando houve dificuldade?"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'roleplay', 21, '{"title":"Roleplay","body":"### Roleplay 1 - Contexto formal\r\n\r\nO aluno responde a uma pessoa da gemeente, medico, escola ou trabalho usando as frases da licao.\r\n\r\n### Roleplay 2 - Contexto informal\r\n\r\nO aluno responde a colega, vizinho ou colega de curso usando forma simples e natural.\r\n\r\n### Roleplay 3 - Problema real\r\n\r\nO aluno nao entende a primeira vez, pede repeticao e completa a tarefa comunicativa."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'erros-comuns', 22, '{"title":"Erros comuns","body":"- Ler aproximacao escrita como pronuncia correta.\r\n- Traduzir palavra por palavra antes de ouvir.\r\n- Nao usar audio nativo como modelo.\r\n- Nao fechar consoantes finais.\r\n- Ignorar reducoes naturais em fala real.\r\n- Bloquear em vez de pedir repeticao."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'quiz', 23, '{"title":"Quiz","body":"1. A referencia principal de pronuncia e:\r\n\r\n```text\r\nA. aproximacao escrita\r\nB. audio nativo\r\nC. traducao inglesa\r\n```\r\n\r\nResposta: B\r\n\r\n2. A aproximacao escrita serve para:\r\n\r\n```text\r\nA. substituir audio\r\nB. apoio inicial\r\nC. provar pronuncia correta\r\n```\r\n\r\nResposta: B\r\n\r\n3. O aluno deve fazer shadowing?\r\n\r\n```text\r\nA. Sim\r\nB. Nao\r\n```\r\n\r\nResposta: A\r\n\r\n4. Se nao entender, o aluno deve:\r\n\r\n```text\r\nA. bloquear\r\nB. pedir repeticao ou ajuda\r\nC. fingir que entendeu\r\n```\r\n\r\nResposta: B\r\n\r\n5. A gramatica da licao deve ser usada em:\r\n\r\n```text\r\nA. frases reais\r\nB. apenas tabela\r\nC. apenas traducao\r\n```\r\n\r\nResposta: A"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'flashcards', 24, '{"title":"Flashcards","body":"```text\r\nnaam - nome - name\r\nvoornaam - primeiro nome - first name\r\nachternaam - apelido/sobrenome - surname\r\nland - pais - country\r\ntaal - lingua/idioma - language\r\nPortugees - portugues - Portuguese\r\nEngels - ingles - English\r\nNederland - Holanda/Paises Baixos - Netherlands\r\nIk ben Henrique. - Eu sou o Henrique. - I am Henrique.\r\nMijn naam is Henrique. - O meu nome e Henrique. - My name is Henrique.\r\nIk kom uit Portugal. - Venho de Portugal. - I come from Portugal.\r\nIk woon in Nederland. - Vivo nos Paises Baixos. - I live in the Netherlands.\r\nWelke taal spreekt u? - Que lingua fala? - Which language do you speak?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'teste-final-auditivo', 25, '{"title":"Teste final auditivo","body":"O aluno ouve:\r\n\r\n1. palavras isoladas\r\n2. frases lentas\r\n3. frases naturais\r\n4. um mini dialogo\r\n5. a frase final em fala natural\r\n\r\nTarefas:\r\n\r\n- identificar palavras-chave\r\n- escolher respostas corretas\r\n- completar palavras ouvidas\r\n- fazer shadowing\r\n- gravar a resposta oral final\r\n- responder a uma pergunta nova com a mesma estrutura"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'criterios-de-dominio', 26, '{"title":"Criterios de dominio","body":"A licao esta concluida quando o aluno consegue:\r\n\r\n- reconhecer vocabulario principal em audio nativo\r\n- usar a gramatica principal em pelo menos 3 frases proprias\r\n- fazer shadowing de pelo menos 3 frases\r\n- compreender forma lenta e natural\r\n- completar exercicios escritos\r\n- responder oralmente sem bloquear\r\n- fazer roleplay com ajuda minima\r\n- acertar pelo menos 4/5 no quiz\r\n- acertar pelo menos 4/5 no teste auditivo\r\n\r\nCriterio final de sobrevivencia real:\r\n\r\n```text\r\nIk ben Henrique. Ik kom uit Portugal. Ik woon in Nederland.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'naam', 'nome', 'name', 'Na palavra `naam`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn naam is Henrique.', 1 from lessons l where l.code = 'A1-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'voornaam', 'primeiro nome', 'first name', 'Na palavra `voornaam`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn voornaam is Henrique.', 2 from lessons l where l.code = 'A1-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'achternaam', 'apelido/sobrenome', 'surname', 'Na palavra `achternaam`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Mijn achternaam is Silva.', 3 from lessons l where l.code = 'A1-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'land', 'pais', 'country', 'Na palavra `land`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Portugal is mijn land.', 4 from lessons l where l.code = 'A1-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'taal', 'lingua/idioma', 'language', 'Na palavra `taal`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Welke taal spreekt u?', 5 from lessons l where l.code = 'A1-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'Portugees', 'portugues', 'Portuguese', 'Na palavra `Portugees`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik spreek Portugees.', 6 from lessons l where l.code = 'A1-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'Engels', 'ingles', 'English', 'Na palavra `Engels`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik spreek Engels.', 7 from lessons l where l.code = 'A1-01';
insert into vocabulary_items(lesson_id, text_nl, translation_pt, translation_en, pronunciation_guidance, example_sentence, order_index)
select l.id, 'Nederland', 'Holanda/Paises Baixos', 'Netherlands', 'Na palavra `Nederland`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.', 'Ik woon in Nederland.', 8 from lessons l where l.code = 'A1-01';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik ben Henrique.', 'Eu sou o Henrique.', 'I am Henrique.', 'Ik ben / Henrique.', 'Ik ben Henrique.', 'Ik ben Henrique.', '''k Ben Henrique.', 'Na frase `Ik ben Henrique.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 1 from lessons l where l.code = 'A1-01';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Mijn naam is Henrique.', 'O meu nome e Henrique.', 'My name is Henrique.', 'Mijn naam / is Henrique.', 'Mijn naam is Henrique.', 'Mijn naam is Henrique.', 'M''n naam is Henrique.', 'Na frase `Mijn naam is Henrique.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 2 from lessons l where l.code = 'A1-01';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik kom uit Portugal.', 'Venho de Portugal.', 'I come from Portugal.', 'Ik kom / uit Portugal.', 'Ik kom uit Portugal.', 'Ik kom uit Portugal.', '''k Kom uit Portugal.', 'Na frase `Ik kom uit Portugal.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 3 from lessons l where l.code = 'A1-01';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Ik woon in Nederland.', 'Vivo nos Paises Baixos.', 'I live in the Netherlands.', 'Ik woon / in Nederland.', 'Ik woon in Nederland.', 'Ik woon in Nederland.', '''k Woon in Nederland.', 'Na frase `Ik woon in Nederland.`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 4 from lessons l where l.code = 'A1-01';
insert into phrases(lesson_id, text_nl, translation_pt, translation_en, sound_blocks, slow_form, natural_form, reduced_form, pronunciation_guidance, order_index)
select l.id, 'Welke taal spreekt u?', 'Que lingua fala?', 'Which language do you speak?', 'Welke taal / spreekt u?', 'Welke taal spreekt u?', 'Welke taal spreek-tu?', 'Welke taal spreekt u?', 'Na frase `Welke taal spreekt u?`, a prioridade e treinar blocos sonoros, nao palavras isoladas. Ouça primeiro a forma lenta, depois a forma natural, e repita mantendo as palavras fortes mais claras e as palavras funcionais mais leves. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Nas vogais arredondadas, aproxime os labios sem criar tensao. A lingua fica mais alta do que em vogais abertas portuguesas. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Depois de conseguir dizer a frase completa, grave a sua voz e compare com o audio nativo: ritmo, reducoes, finais de palavra e entoacao devem soar naturais, nao traduzidos do portugues ou do ingles.', 5 from lessons l where l.code = 'A1-01';
