insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A1-03', 'Artigos de, het, een', 'distinguir `de`, `het` e `een`', 2, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar a lingua em situacoes reais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Artigos `de`, `het` e `een` aparecem em quase todas as frases. O aluno nao precisa dominar todas as regras ainda, mas precisa reconhecer e usar artigos com palavras comuns.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nMedewerker: Heeft u het formulier?\r\nAluno: Ja, ik heb een formulier en de brief.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- distinguir `de`, `het` e `een`\r\n- usar artigos com palavras frequentes\r\n- reconhecer `het` reduzido para `''t`\r\n- perceber que genero gramatical nao e igual a portugues\r\n- usar `een` como artigo indefinido\r\n- fazer frases com objetos reais\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk heb een vraag. Ik heb het formulier. De afspraak is vandaag.\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk heb een vraag.\r\nHet nummer is goed.\r\nDe afspraak is vandaag.\r\nIk heb het formulier.\r\nDat is een brief.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-03';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `de naam`\r\n\r\nTraducao PT: o nome  \r\nTraducao EN: the name  \r\nAudio nativo: `audio/A1-03/words/de-naam.native.nl.mp3`  \r\nAproximacao inicial PT: `duh naam`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `de naam`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer de forte como portugues.\r\n- EN: dizer the.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe naam is goed.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nde naam\r\nde naam em bloco\r\nDe naam is goed.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `de naam` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `de naam` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `het huis`\r\n\r\nTraducao PT: a casa  \r\nTraducao EN: the house  \r\nAudio nativo: `audio/A1-03/words/het-huis.native.nl.mp3`  \r\nAproximacao inicial PT: `ut huis`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `het huis`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ui`, arredonde ligeiramente os labios e deixe a vogal mover-se; nao transforme em `ai`, `oi` ou `u` portugues. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer ret/het forte.\r\n- EN: dizer hut/house.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHet huis is klein.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhet huis\r\nhet huis em bloco\r\nHet huis is klein.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `het huis` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `het huis` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `een formulier`\r\n\r\nTraducao PT: um formulario  \r\nTraducao EN: a form  \r\nAudio nativo: `audio/A1-03/words/een-formulier.native.nl.mp3`  \r\nAproximacao inicial PT: `un for-mu-LIR`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `een formulier`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer em formulario.\r\n- EN: dizer one form sempre.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een formulier.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\neen formulier\r\neen formulier em bloco\r\nIk heb een formulier.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `een formulier` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `een formulier` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `de brief`\r\n\r\nTraducao PT: a carta  \r\nTraducao EN: the letter  \r\nAudio nativo: `audio/A1-03/words/de-brief.native.nl.mp3`  \r\nAproximacao inicial PT: `duh brief`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `de brief`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer briefe.\r\n- EN: dizer brief ingles.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe brief is hier.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nde brief\r\nde brief em bloco\r\nDe brief is hier.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `de brief` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `de brief` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `het nummer`\r\n\r\nTraducao PT: o numero  \r\nTraducao EN: the number  \r\nAudio nativo: `audio/A1-03/words/het-nummer.native.nl.mp3`  \r\nAproximacao inicial PT: `ut NU-mer`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `het nummer`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer numero portugues.\r\n- EN: dizer number.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHet nummer is 27.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhet nummer\r\nhet nummer em bloco\r\nHet nummer is 27.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `het nummer` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `het nummer` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `de afspraak`\r\n\r\nTraducao PT: a marcacao  \r\nTraducao EN: the appointment  \r\nAudio nativo: `audio/A1-03/words/de-afspraak.native.nl.mp3`  \r\nAproximacao inicial PT: `duh AF-spraak`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `de afspraak`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer esfpraak.\r\n- EN: dizer appointment rhythm.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe afspraak is vandaag.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nde afspraak\r\nde afspraak em bloco\r\nDe afspraak is vandaag.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `de afspraak` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `de afspraak` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `een vraag`\r\n\r\nTraducao PT: uma pergunta  \r\nTraducao EN: a question  \r\nAudio nativo: `audio/A1-03/words/een-vraag.native.nl.mp3`  \r\nAproximacao inicial PT: `un vraakh`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `een vraag`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer verraag.\r\n- EN: dizer frag.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een vraag.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\neen vraag\r\neen vraag em bloco\r\nIk heb een vraag.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `een vraag` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `een vraag` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `het antwoord`\r\n\r\nTraducao PT: a resposta  \r\nTraducao EN: the answer  \r\nAudio nativo: `audio/A1-03/words/het-antwoord.native.nl.mp3`  \r\nAproximacao inicial PT: `ut ANT-voort`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `het antwoord`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `oo`, mantenha uma vogal longa e arredondada, sem transformar num `ou` portugues ou ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O `w` neerlandes fica entre o `v` e o `w` ingles em muitos falantes. Encoste labios/dentes de forma leve e confirme sempre pelo audio. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Treine por blocos de som. A palavra principal recebe mais energia, enquanto artigos, pronomes e auxiliares podem ficar mais leves em fala natural. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer antwoordi.\r\n- EN: dizer answer.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHet antwoord is ja.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhet antwoord\r\nhet antwoord em bloco\r\nHet antwoord is ja.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `het antwoord` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `het antwoord` em audio nativo e usa a palavra numa resposta A1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-03';
