insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A1-05', 'Verbos zijn e hebben', 'usar `ik ben`', 4, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar a lingua em situacoes reais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"`Zijn` e `hebben` sao indispensaveis para dizer identidade, estado, posse, idade, documentos, marcacoes e necessidades.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nMedewerker: Heeft u een afspraak?\r\nAluno: Ja, ik heb een afspraak. Ik ben op tijd.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- usar `ik ben`\r\n- usar `ik heb`\r\n- reconhecer `bent u` e `heeft u`\r\n- falar de idade e documentos\r\n- responder em contexto formal\r\n- ouvir formas naturais de `heb` e `ben`\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nIk ben hier. Ik heb een afspraak. Heeft u tijd?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nIk ben hier.\r\nIk heb een afspraak.\r\nHeeft u tijd?\r\nBent u klaar?\r\nWij zijn thuis.\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-05';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `ben`\r\n\r\nTraducao PT: sou/estou  \r\nTraducao EN: am  \r\nAudio nativo: `audio/A1-05/words/ben.native.nl.mp3`  \r\nAproximacao inicial PT: `ben`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `ben`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer bene.\r\n- EN: dizer been.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ben hier.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nben\r\nben em bloco\r\nIk ben hier.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `ben` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `ben` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `bent`\r\n\r\nTraducao PT: e/esta formal/informal  \r\nTraducao EN: are  \r\nAudio nativo: `audio/A1-05/words/bent.native.nl.mp3`  \r\nAproximacao inicial PT: `bent`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `bent`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: perder t.\r\n- EN: dizer bent ingles forte.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nBent u klaar?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbent\r\nbent em bloco\r\nBent u klaar?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `bent` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `bent` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `is`\r\n\r\nTraducao PT: e/esta  \r\nTraducao EN: is  \r\nAudio nativo: `audio/A1-05/words/is.native.nl.mp3`  \r\nAproximacao inicial PT: `is`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `is`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer izi.\r\n- EN: alongar.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHij is thuis.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nis\r\nis em bloco\r\nHij is thuis.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `is` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `is` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `zijn`\r\n\r\nTraducao PT: sao/estao/ser  \r\nTraducao EN: are/to be  \r\nAudio nativo: `audio/A1-05/words/zijn.native.nl.mp3`  \r\nAproximacao inicial PT: `zein`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `zijn`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer zin.\r\n- EN: dizer zine.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nWij zijn hier.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nzijn\r\nzijn em bloco\r\nWij zijn hier.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `zijn` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `zijn` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `heb`\r\n\r\nTraducao PT: tenho  \r\nTraducao EN: have  \r\nAudio nativo: `audio/A1-05/words/heb.native.nl.mp3`  \r\nAproximacao inicial PT: `hep`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `heb`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer hebe.\r\n- EN: dizer have.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb tijd.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nheb\r\nheb em bloco\r\nIk heb tijd.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `heb` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `heb` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `heeft`\r\n\r\nTraducao PT: tem formal/ele tem  \r\nTraducao EN: has/have formal  \r\nAudio nativo: `audio/A1-05/words/heeft.native.nl.mp3`  \r\nAproximacao inicial PT: `heeft`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `heeft`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ee`, mantenha uma vogal longa e clara, com a boca relativamente estavel e sem transformar no som ingles de `day`. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: calar h.\r\n- EN: dizer heft ingles.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nHeeft u tijd?\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nheeft\r\nheeft em bloco\r\nHeeft u tijd?\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `heeft` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `heeft` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `afspraak`\r\n\r\nTraducao PT: marcacao  \r\nTraducao EN: appointment  \r\nAudio nativo: `audio/A1-05/words/afspraak.native.nl.mp3`  \r\nAproximacao inicial PT: `AF-spraak`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `afspraak`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer afspraak com e.\r\n- EN: usar appointment.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een afspraak.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nafspraak\r\nafspraak em bloco\r\nIk heb een afspraak.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `afspraak` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `afspraak` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `tijd`\r\n\r\nTraducao PT: tempo/hora  \r\nTraducao EN: time  \r\nAudio nativo: `audio/A1-05/words/tijd.native.nl.mp3`  \r\nAproximacao inicial PT: `teit`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `tijd`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer tide.\r\n- EN: dizer tied.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb tijd.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntijd\r\ntijd em bloco\r\nIk heb tijd.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `tijd` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `tijd` em audio nativo e usa a palavra numa resposta A1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-05';
