insert into lessons(level_id, code, title, objective, order_index, status, estimated_minutes)
select lv.id, 'A1-09', 'Transporte basico', 'perguntar destino', 8, 'published', 45
from levels lv
join courses c on c.id = lv.course_id where c.code = 'nederstart-dutch' and lv.code = 'A1'
on conflict (code) do update set title = excluded.title, objective = excluded.objective, order_index = excluded.order_index, status = excluded.status, estimated_minutes = excluded.estimated_minutes;

insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'regra-oficial-de-pronuncia-e-audicao', 1, '{"title":"Regra oficial de pronuncia e audicao","body":"Nesta licao, a pronuncia escrita e apenas uma aproximacao inicial. A referencia correta e sempre:\r\n\r\n1. audio nativo\r\n2. explicacao fisica do som\r\n3. demonstracao visual da boca e da lingua\r\n4. shadowing\r\n5. aproximacao escrita PT/EN como apoio temporario\r\n\r\nO aluno nao deve memorizar a aproximacao escrita como se fosse a pronuncia real. O objetivo e ouvir, imitar, ajustar e usar a lingua em situacoes reais."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'contexto-real-de-utilizacao', 2, '{"title":"Contexto real de utilizacao","body":"Transportes sao essenciais para trabalho, escola, medico e integracao. O aluno aprende a reconhecer destino, plataforma, autocarro/comboio, atraso e bilhete.\r\n\r\nSituacao exemplo:\r\n\r\n```text\r\nReiziger: Welke trein gaat naar Amsterdam?\r\nAluno: Gaat deze trein naar Amsterdam?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'objetivos-da-licao', 3, '{"title":"Objetivos da licao","body":"No fim desta licao, o aluno deve conseguir:\r\n\r\n- perguntar destino\r\n- entender comboio/autocarro\r\n- usar `naar`\r\n- reconhecer atraso\r\n- pedir ajuda na estacao\r\n- fazer roleplay de transporte\r\n\r\nObjetivo oral final:\r\n\r\n```text\r\nGaat deze trein naar Amsterdam? Op welk perron?\r\n```\r\n\r\nObjetivo auditivo final:\r\n\r\nO aluno reconhece, sem ler:\r\n\r\n```text\r\nGaat deze trein naar Amsterdam?\r\nWaar is het station?\r\nDe bus is te laat.\r\nIk heb een kaartje.\r\nOp welk perron?\r\n```"}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-09';
insert into lesson_content_blocks(lesson_id, block_type, order_index, content_json, source_language_code, target_language_code)
select l.id, 'vocabulario-principal', 4, '{"title":"Vocabulario principal","body":"### Palavra 1\r\n\r\nPalavra: `trein`\r\n\r\nTraducao PT: comboio/trem  \r\nTraducao EN: train  \r\nAudio nativo: `audio/A1-09/words/trein.native.nl.mp3`  \r\nAproximacao inicial PT: `trein`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `trein`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `ij/ei`, use o audio nativo como referencia: e um som frontal com movimento curto, sem virar o `ai` portugues nem o `ay` ingles. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer trem.\r\n- EN: dizer train ingles.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe trein komt.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\ntrein\r\ntrein em bloco\r\nDe trein komt.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `trein` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `trein` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 2\r\n\r\nPalavra: `bus`\r\n\r\nTraducao PT: autocarro/onibus  \r\nTraducao EN: bus  \r\nAudio nativo: `audio/A1-09/words/bus.native.nl.mp3`  \r\nAproximacao inicial PT: `bus`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `bus`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Feche as consoantes finais de forma seca. Para falantes de portugues, o ponto principal e nao acrescentar uma vogal final; para falantes de ingles, e evitar transformar o final num som de `-ed`. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer bus portugues.\r\n- EN: dizer bas.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe bus is laat.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nbus\r\nbus em bloco\r\nDe bus is laat.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `bus` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `bus` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 3\r\n\r\nPalavra: `station`\r\n\r\nTraducao PT: estacao  \r\nTraducao EN: station  \r\nAudio nativo: `audio/A1-09/words/station.native.nl.mp3`  \r\nAproximacao inicial PT: `sta-SHON`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `station`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Comece pelo audio nativo e observe como a palavra e produzida em fala lenta e natural. Repare na abertura da boca, na posicao da lingua e no fecho das consoantes finais. Para falantes de portugues, o cuidado principal e evitar adicionar vogais finais e evitar ritmo silabico. Para falantes de ingles, o cuidado principal e nao transferir stress e vogais do ingles. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer estation.\r\n- EN: dizer station ingles.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk ben op het station.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nstation\r\nstation em bloco\r\nIk ben op het station.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `station` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `station` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 4\r\n\r\nPalavra: `perron`\r\n\r\nTraducao PT: plataforma  \r\nTraducao EN: platform  \r\nAudio nativo: `audio/A1-09/words/perron.native.nl.mp3`  \r\nAproximacao inicial PT: `pe-RON`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `perron`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer perrom.\r\n- EN: dizer platform.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nPerron drie.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nperron\r\nperron em bloco\r\nPerron drie.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `perron` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `perron` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 5\r\n\r\nPalavra: `kaartje`\r\n\r\nTraducao PT: bilhete  \r\nTraducao EN: ticket  \r\nAudio nativo: `audio/A1-09/words/kaartje.native.nl.mp3`  \r\nAproximacao inicial PT: `KAAR-tchuh`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `kaartje`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Para `aa`, mantenha a vogal longa e estavel. Abra a boca de forma natural e nao corte o som demasiado cedo. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer cartche.\r\n- EN: dizer ticket.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nIk heb een kaartje.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nkaartje\r\nkaartje em bloco\r\nIk heb een kaartje.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `kaartje` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `kaartje` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 6\r\n\r\nPalavra: `vertraging`\r\n\r\nTraducao PT: atraso  \r\nTraducao EN: delay  \r\nAudio nativo: `audio/A1-09/words/vertraging.native.nl.mp3`  \r\nAproximacao inicial PT: `ver-TRAA-ghing`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `vertraging`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. O som inicial escrito com `v` pode soar mais proximo de `v` ou `f` dependendo do falante e da regiao. O aluno deve imitar o audio nativo, nao a grafia portuguesa ou inglesa. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer vertraging sem g.\r\n- EN: dizer delay.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe trein heeft vertraging.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nvertraging\r\nvertraging em bloco\r\nDe trein heeft vertraging.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `vertraging` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `vertraging` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 7\r\n\r\nPalavra: `richting`\r\n\r\nTraducao PT: direcao  \r\nTraducao EN: direction  \r\nAudio nativo: `audio/A1-09/words/richting.native.nl.mp3`  \r\nAproximacao inicial PT: `RIKH-ting`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `richting`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. Quando aparecer `g`, `ch` ou `sch`, produza friccao atras da boca: a parte de tras da lingua aproxima-se do palato mole e o ar passa sem bloquear. Nao transforme este som num `r` portugues nem num `h` ingles. Quando aparecer `ng`, feche o som pelo nariz, como no fim de `parking`. Nao acrescente uma vogal depois do `ng`. O `r` deve ser leve e curto. Nao force uma vibracao forte portuguesa e nao use o `r` ingles como modelo principal. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: dizer rikting sem garganta.\r\n- EN: dizer direction.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nRichting Amsterdam.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nrichting\r\nrichting em bloco\r\nRichting Amsterdam.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `richting` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `richting` em audio nativo e usa a palavra numa resposta A1 curta.\r\n\r\n### Palavra 8\r\n\r\nPalavra: `halte`\r\n\r\nTraducao PT: paragem  \r\nTraducao EN: stop  \r\nAudio nativo: `audio/A1-09/words/halte.native.nl.mp3`  \r\nAproximacao inicial PT: `HAL-tuh`  \r\nAproximacao inicial EN: native-audio-first support\r\n\r\nExplicacao fisica:\r\n\r\nNa palavra `halte`, comece sempre pelo audio nativo. Observe a boca do falante, a posicao da lingua e o ponto onde o som e produzido antes de usar qualquer aproximacao escrita. O `h` deve sair com ar leve desde a garganta, sem desaparecer como acontece muitas vezes em portugues e sem ficar exagerado. Repita primeiro devagar, depois em frase natural. O criterio nao e soar portugues ou ingles, mas aproximar-se progressivamente do modelo nativo.\r\n\r\nErros comuns:\r\n\r\n- PT: calar h.\r\n- EN: dizer halt ingles.\r\n\r\nExemplo em contexto:\r\n\r\n```text\r\nDe halte is hier.\r\n```\r\n\r\nExercicio de repeticao:\r\n\r\n```text\r\nhalte\r\nhalte em bloco\r\nDe halte is hier.\r\n```\r\n\r\nExercicio de audicao:\r\n\r\nO aluno ouve `halte` isolado, depois dentro de uma frase lenta e depois dentro de uma frase natural. Deve identificar a palavra sem ler.\r\n\r\nCriterio de dominio:\r\n\r\nO aluno reconhece `halte` em audio nativo e usa a palavra numa resposta A1 curta."}'::jsonb, 'pt', 'nl' from lessons l where l.code = 'A1-09';
